/**
 * Ref serializer — converts RefData to the Elementum API's
 * ValueReferenceInput JSON format.
 */
import { toRefData } from "../../entities/shared/ref.js";
// ---------------------------------------------------------------------------
// Serialization
// ---------------------------------------------------------------------------
export function serializeRefData(data) {
    switch (data.kind) {
        case "static":
            return { value: data.value };
        case "trigger":
            // Trigger ref names are emitted case-preserving. Built-in triggers
            // (webhook, record*, attachment, commentAdded) register camelCase
            // parameter names on the platform (`contentType`, `recordId`,
            // `aspectReferences`, …), so lowercasing them here breaks the
            // ValueReference UUID-v5 hash lookup and leaves the saved input
            // orphaned in the UI. onDemand triggers, which do lowercase their
            // schema names, have a post-pass in `serializeAutomation` that
            // lowercases the root segment of any trigger ref in the result tree.
            return { triggerReference: { name: data.name } };
        case "task":
            return { taskReference: { taskRefKey: data.actionRefKey, name: data.name } };
        case "forEach":
            return {
                forEachReference: {
                    forEachTaskRefKey: data.forEachActionName,
                    name: data.name,
                },
            };
        case "template":
            return serializeTemplate(data);
        case "variableParam":
            return serializeVariableParamMarker(data);
        case "secret":
            return { secretReference: { secretId: data.secretId } };
    }
}
/**
 * Characters used to escape a literal `$` that appears immediately before
 * a `{{{pN}}}` placeholder. Without this, the Mobius UI's Lexical editor
 * sees `${{p1}}` and treats it as an escape sequence, rendering the
 * placeholder as literal text instead of as the reference chip.
 *
 * The UI renderer strips matching zero-width joiners before displaying
 * the template, so `$` + joiner + `{{{p1}}}` round-trips visually as
 * `$` + chip. No other characters in template strings should contain
 * U+2060 (word joiner), so the escape is reversible without ambiguity.
 */
const DOLLAR_PLACEHOLDER_ESCAPE = "\u2060"; // WORD JOINER
function serializeTemplate(data) {
    let templateStr = "";
    const parameters = [];
    let paramIndex = 1;
    for (const part of data.parts) {
        if (typeof part === "string") {
            templateStr += part;
        }
        else {
            // Defense-in-depth for the `$`-before-placeholder collision (see
            // plans/edk-shortcomings.md #27). `template()` also rejects the
            // literal-string form at the type level; this pass handles dynamic
            // / computed string fragments the type system can't inspect.
            if (templateStr.length > 0 && templateStr.endsWith("$")) {
                templateStr += DOLLAR_PLACEHOLDER_ESCAPE;
            }
            const paramName = `p${paramIndex++}`;
            templateStr += `{{{${paramName}}}}`;
            parameters.push({ value: { name: paramName, value: serializeRefData(part) } });
        }
    }
    return { templateReference: { template: templateStr, parameters } };
}
/**
 * Placeholder marker emitted for variableParam refs.
 * Resolved to real `{ variableReference: { id, name } }` by
 * `resolveVariableParamMarkers` after all tasks are serialized.
 */
function serializeVariableParamMarker(data) {
    return { __variableParamRef: { variableTaskRefKey: data.variableActionRefKey, name: data.name } };
}
/**
 * Serialize a ValueOrRef to a ValueReferenceInput JSON.
 * Literal values become { value: ... }.
 */
export function serializeValueOrRef(v) {
    return serializeRefData(toRefData(v));
}
